import{V as e,ht as t,nt as n,tt as r}from"./chunks/framework.wxcks8ca.js";import"./chunks/assets.NJs4UO-Q.js";var i=JSON.parse(`{"title":"定制化","description":"","frontmatter":{},"headers":[],"relativePath":"kimi-code-for-vscode/customization.md","filePath":"zh/kimi-code-for-vscode/customization.md"}`),a={name:`kimi-code-for-vscode/customization.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="定制化" tabindex="-1">定制化 <a class="header-anchor" href="#定制化" aria-label="Permalink to “定制化”">​</a></h1><div class="warning custom-block"><p class="custom-block-title">VS Code 插件适配中</p><p>Kimi Code for VS Code 目前仅对旧版 Python CLI 用户开放新增安装。已安装插件的老用户升级新版 CLI 后仍可继续使用，其他 TS 版本 CLI 用户暂不支持安装。</p></div><h2 id="mcp-服务器" tabindex="-1">MCP 服务器 <a class="header-anchor" href="#mcp-服务器" aria-label="Permalink to “MCP 服务器”">​</a></h2><p>MCP（Model Context Protocol）服务器可为 Kimi 扩展外部工具与服务。通过操作菜单（齿轮图标）→ <strong>MCP Servers</strong> 进行管理。</p><h3 id="传输类型" tabindex="-1">传输类型 <a class="header-anchor" href="#传输类型" aria-label="Permalink to “传输类型”">​</a></h3><p>支持两种传输类型：</p><ul><li><strong>stdio</strong>：本地命令行工具，需指定命令、参数和环境变量</li><li><strong>http</strong>：远程服务，需指定 URL，可选 OAuth</li></ul><h3 id="推荐服务器" tabindex="-1">推荐服务器 <a class="header-anchor" href="#推荐服务器" aria-label="Permalink to “推荐服务器”">​</a></h3><p><img src="/code/docs/images/zh/vscode/kimi-code-mcp.png" alt="Kimi Code MCP Servers"></p><p>提供推荐服务器的一键安装：</p><table tabindex="0"><thead><tr><th>服务器</th><th>用途</th></tr></thead><tbody><tr><td>Playwright</td><td>浏览器自动化</td></tr><tr><td>Context7</td><td>实时文档</td></tr><tr><td>GitHub</td><td>API 访问</td></tr></tbody></table><p>部分服务器需 OAuth 认证，点击授权按钮打开流程，或重置凭证。保存前可测试连接以验证服务器可用性。</p>`,12)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};